'use client';

import { useState, useMemo } from 'react';
import { useRouter } from 'next/router';

function ClubCard({ club }) {
  const router = useRouter();

  const handleClubClick = () => {
    if (!club.modalidades || club.modalidades.length === 0) {
      sessionStorage.setItem(
        'clubNav',
        JSON.stringify({ id: club.id, nombre: club.nombre })
      );
      router.push(`/clubs/${encodeURIComponent(club.nombre)}`);
    } else {
      sessionStorage.setItem(
        'teamNav',
        JSON.stringify({ id: club.id, nombre: club.nombre })
      );
      router.push(`/team/${encodeURIComponent(club.nombre)}`);
    }
  };

  const socials = [];
  if (club.redesSociales) {
    if (Array.isArray(club.redesSociales)) {
      socials.push(...club.redesSociales);
    } else if (typeof club.redesSociales === 'object') {
      socials.push(
        ...Object.entries(club.redesSociales)
          .filter(([, value]) => value)
          .map(([red, url]) => ({ red, url }))
      );
    }
  }

  return (
    <article className="arg-map-club" onClick={handleClubClick}>
      <div className="arg-map-club-logo">
        {club.logo ? (
          <img
            src={club.logo}
            alt={`Logo de ${club.nombre}`}
            className="arg-map-club-img"
          />
        ) : (
          <span>{club.nombre?.charAt(0) ?? '?'}</span>
        )}
      </div>
      <div className="arg-map-club-body">
        <strong>{club.nombre}</strong>
        <span>{club.ciudad || 'Ciudad no informada'}</span>
        {socials.length > 0 && (
          <div className="arg-map-socials">
            {socials.map((social, index) => (
              <a
                key={`${social.red}-${index}`}
                href={social.url}
                target="_blank"
                rel="noreferrer"
                title={social.red}
                onClick={(e) => e.stopPropagation()}
              >
                {social.red}
              </a>
            ))}
          </div>
        )}
      </div>
    </article>
  );
}

function ClubsPanel({ provinceId, clubs }) {
  if (!provinceId) {
    return (
      <aside className="arg-map-panel arg-map-panel-empty">
        <h3>Clubes de Buhurt Argentina</h3>
        <p>
          Pasá el mouse sobre una zona del mapa para ver sus clubes.
          También podés hacer click para mantener la selección.
        </p>
      </aside>
    );
  }

  const displayName = provinceId
    .split('-')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');

  return (
    <aside className="arg-map-panel">
      <div className="arg-map-panel-header">
        <h3>{displayName}</h3>
        <span className="arg-map-count">{clubs.length}</span>
      </div>
      {clubs.length === 0 ? (
        <p className="arg-map-no-clubs">
          Todavía no hay clubes registrados en esta zona.
        </p>
      ) : (
        <div className="arg-map-clubs">
          {clubs.map((club) => (
            <ClubCard key={club.id ?? club.nombre} club={club} />
          ))}
        </div>
      )}
    </aside>
  );
}

const PROVINCE_ALIASES = {
  'gran-buenos-aires': 'amba',
  'gba': 'amba',
  'caba': 'amba',
  'capital-federal': 'amba',
  'ciudad-autonoma-de-buenos-aires': 'amba',
  'bs-as': 'amba',
  'bsas': 'amba',
  'autonoma-de-buenos-aires': 'amba',
  'ciudad-de-buenos-aires': 'amba',
};

function normalizeProvince(value) {
  if (!value || String(value).trim() === '') return 'amba';

  const normalized = String(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');

  return PROVINCE_ALIASES[normalized] || normalized;
}

